#include <cstdio>
#include <vector>
#include <algorithm>

struct Point { long long x, y, d; };

int main() {
    int n, k;
    scanf("%d %d", &n, &k);
    std::vector<Point> p(n);
    for (int i = 0; i < n; ++i) {
        scanf("%lld %lld", &p[i].x, &p[i].y);
        p[i].d = p[i].x * p[i].x + p[i].y * p[i].y;
    }

    std::sort(p.begin(), p.end(), [](const Point &a, const Point &b) {
        if (a.d != b.d) return a.d < b.d;
        if (a.x != b.x) return a.x < b.x;
        return a.y < b.y;
    });

    for (int i = 0; i < k; ++i)
        printf("%lld %lld\n", p[i].x, p[i].y);
    return 0;
}
